# Fixed DC01 delivery. Local signed preparation; no GPO/SYSVOL/endpoint apply.
param([ValidateSet('Inspect','Prepare','Verify')][string]$Mode='Inspect',
 [Parameter(Mandatory=$true)][string]$DraftZip)
$ErrorActionPreference='Stop';Set-StrictMode -Version 2
Import-Module (Join-Path $PSHOME 'Modules\Microsoft.PowerShell.Security\Microsoft.PowerShell.Security.psd1') -ErrorAction Stop
Add-Type -AssemblyName System.IO.Compression
$sourceCommit='5069c9f5682e064391c601c6dd1d3d648bdb5a86'
$embedded=''
$archivePin='c70dfad7e4d4180d80a4bf63a8d7f220eba47a79494325bb86a8eb631d3ad18f'
$pins=@{'New-AuthWireDeploymentCandidate.ps1'='8043963d673488b6a07f91e9fe228675134e4d067270e7d30a8084d945316a01';'Get-AuthWireMachineSignerMetadata.ps1'='2332082ac59f9adec7ac47d2bd9e80e3ca6733f34ba75e256ac1abb33769d908';'New-AuthWireCombinedCandidate.ps1'='fa9a494a1349ad776b5ffdae9e27e2b896b1ba616dedc5e96b5da3f1728c6289';'Install-AuthWire.ps1'='ab1a11c68381006173518df77deeb0d32fc56e0b28cc260c42b7378c624be14a'}
$draftPin='5dd35e4d28f6b6495223224f89d339c4cdd595099df5ac726b812238feca0ce5'
$sources=$null;$preparedNow=$false;$stage='preflight'
function Get-DeliveryHash([byte[]]$Bytes){$h=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($h.ComputeHash($Bytes))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()}}
function Assert-DeliveryLocalPath([string]$Path){
 if(-not [IO.Path]::IsPathRooted($Path) -or $Path.StartsWith('\\') -or $Path -match ':.*:'){throw 'LOCAL_PATH_REQUIRED'}
 $p=[IO.Path]::GetFullPath($Path);$part=$p
 while($part){if(Test-Path -LiteralPath $part){if((Get-Item -LiteralPath $part -Force).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'REPARSE_PATH_REJECTED'}};$parent=[IO.Path]::GetDirectoryName($part);if($parent -eq $part){break};$part=$parent}
 return $p
}
try{
 if([Environment]::MachineName -ine 'DC01' -or -not [Environment]::Is64BitProcess -or $PSVersionTable.PSVersion.Major -ne 5){throw 'DC01_NATIVE_WINDOWS_POWERSHELL_5_REQUIRED'}
 $system=Get-CimInstance Win32_ComputerSystem -Property Domain,PartOfDomain
 if(-not $system.PartOfDomain -or $system.Domain -ine 'vizyonveri.local'){throw 'EXPECTED_DOMAIN_REQUIRED'}
 $identity=[Security.Principal.WindowsIdentity]::GetCurrent()
 try{if(-not ([Security.Principal.WindowsPrincipal]::new($identity)).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'ELEVATED_OPERATOR_REQUIRED'}}finally{$identity.Dispose()}
 $DraftZip=Assert-DeliveryLocalPath $DraftZip
 $inputItem=Get-Item -LiteralPath $DraftZip -Force
 if($inputItem.PSIsContainer -or $inputItem.Length -gt 1048576 -or (Get-DeliveryHash ([IO.File]::ReadAllBytes($DraftZip))) -cne $draftPin){throw 'EXACT_CUSTOMER_DRAFT_REQUIRED'}
 $raw=[Convert]::FromBase64String($embedded)
 if((Get-DeliveryHash $raw) -cne $archivePin){throw 'SOURCE_ARCHIVE_CHANGED'}
 $memory=[IO.MemoryStream]::new($raw,$false);$zip=$null;$files=@{};$total=0
 try{
  $zip=[IO.Compression.ZipArchive]::new($memory,[IO.Compression.ZipArchiveMode]::Read,$false)
  if($zip.Entries.Count -ne $pins.Count){throw 'SOURCE_FILE_SET_REJECTED'}
  foreach($entry in $zip.Entries){
   if($entry.FullName -cnotin @($pins.Keys) -or $files.ContainsKey($entry.FullName) -or $entry.Length -gt 262144){throw 'SOURCE_FILE_SET_REJECTED'}
   $stream=$entry.Open();$out=[IO.MemoryStream]::new()
   try{[byte[]]$buffer=New-Object byte[] 4096;while(($n=$stream.Read($buffer,0,$buffer.Length)) -gt 0){$out.Write($buffer,0,$n);if($out.Length -gt 262144){throw 'SOURCE_CONTENT_LIMIT'}};$bytes=$out.ToArray()}finally{$stream.Dispose();$out.Dispose()}
   $total+=$bytes.Length;if($total -gt 524288 -or (Get-DeliveryHash $bytes) -cne $pins[$entry.FullName]){throw 'SOURCE_CONTENT_CHANGED'}
   $files[$entry.FullName]=$bytes
  }
 }finally{if($zip){$zip.Dispose()};$memory.Dispose()}
 $sources=Assert-DeliveryLocalPath (Join-Path $env:ProgramData ('AuthWire-CombinedSigningSources-'+$archivePin.Substring(0,16)))
 if(-not (Test-Path -LiteralPath $sources)){
  $null=New-Item -ItemType Directory -Path $sources
  $acl=[Security.AccessControl.DirectorySecurity]::new();$acl.SetSecurityDescriptorSddlForm('O:BAG:BAD:P(A;OICI;FA;;;SY)(A;OICI;FA;;;BA)');Set-Acl -LiteralPath $sources -AclObject $acl
  foreach($n in $files.Keys){[IO.File]::WriteAllBytes((Join-Path $sources $n),[byte[]]$files[$n])};$preparedNow=$true
 }
 $acl=Get-Acl -LiteralPath $sources
 if(-not $acl.AreAccessRulesProtected -or $acl.GetOwner([Security.Principal.SecurityIdentifier]).Value -cne 'S-1-5-32-544'){throw 'SOURCE_ACL_REJECTED'}
 $rules=@($acl.GetAccessRules($true,$true,[Security.Principal.SecurityIdentifier]))
 if($rules.Count -ne 2 -or @($rules|Where-Object{$_.IdentityReference.Value -cnotin @('S-1-5-18','S-1-5-32-544') -or $_.AccessControlType.ToString() -cne 'Allow' -or [int]$_.FileSystemRights -ne 2032127 -or $_.IsInherited}).Count){throw 'SOURCE_ACL_REJECTED'}
 $entries=@(Get-ChildItem -LiteralPath $sources -Force)
 if($entries.Count -ne $pins.Count){throw 'EXISTING_SOURCE_SET_REJECTED'}
 foreach($n in $pins.Keys){$p=Assert-DeliveryLocalPath (Join-Path $sources $n);$item=Get-Item -LiteralPath $p -Force;if($item.PSIsContainer -or $item.Length -gt 262144 -or (Get-DeliveryHash ([IO.File]::ReadAllBytes($p))) -cne $pins[$n]){throw 'EXISTING_SOURCE_CHANGED'}}
 # Import function definitions only; dependency entry points are never invoked.
 foreach($n in @('New-AuthWireDeploymentCandidate.ps1','Get-AuthWireMachineSignerMetadata.ps1','New-AuthWireCombinedCandidate.ps1')){
  $t=$null;$e=$null;$ast=[Management.Automation.Language.Parser]::ParseFile((Join-Path $sources $n),[ref]$t,[ref]$e)
  if($e.Count){throw 'REVIEWED_SOURCE_SYNTAX_REJECTED'}
  foreach($f in $ast.EndBlock.Statements|Where-Object{$_ -is [Management.Automation.Language.FunctionDefinitionAst]}){. ([scriptblock]::Create($f.Extent.Text))}
 }
 $stage='local_candidate_preparation'
 $result=Invoke-AuthWireCombinedCandidate -Mode $Mode -DraftZip $DraftZip -ExpectedDraftSha256 $draftPin `
  -InstallerTemplatePath (Join-Path $sources 'Install-AuthWire.ps1') -ExpectedInstallerTemplateSha256 $pins['Install-AuthWire.ps1'] `
  -PublisherThumbprint 'FFC134BC305757457163F99C7479B4168E397129' -ServiceSid 'S-1-5-21-34256453-3348971241-2809240126-1648' `
  -ExpectedKeyName 'tq-AuthWireConnectorCodeSigning-4c23eebe-15cb8856-8d31-4e48-8c7b-ebe0c842cb2f' `
  -ExpectedUniqueName '6d83645dd6648563b32f0fdecaf3d56e_1fed02ca-1f1d-4faf-839e-e8eb2f0eff4a' `
  -ExpectedKeySddl 'O:BAG:DUD:PAI(A;;FA;;;SY)(A;;FA;;;BA)(A;;FR;;;S-1-5-21-34256453-3348971241-2809240126-1648)' `
  -OutputParent (Join-Path $env:ProgramData 'AuthWire-CombinedCandidates-4c23eebe071546d188eea2e96ad7ee46')
 if((Get-DeliveryHash ([IO.File]::ReadAllBytes($DraftZip))) -cne $draftPin){throw 'ORIGINAL_DRAFT_POSTCHECK_FAILED'}
 [pscustomobject]@{Event='WINDOWS_COMBINED_SIGNING_DELIVERY';ToolVersion='1.0.0';Mode=$Mode;SourceCommit=$sourceCommit;SourcesDirectory=$sources;SourcesPreparedNow=$preparedNow;Stage='verified';Result=$result;OriginalDraftPreserved=$true;AdChanged=$false;GpoChanged=$false;PermanentConnectorChanged=$false;CanApplyGpo=$false}|ConvertTo-Json -Depth 7
}catch{
 [pscustomobject]@{Event='WINDOWS_COMBINED_SIGNING_DELIVERY_FAILED';Mode=$Mode;Stage=$stage;SourcesDirectory=$sources;Error=$_.Exception.Message;ChangesMayBePartial=$true;CanApplyGpo=$false}|ConvertTo-Json -Depth 5
 throw
}
